```python
def media(notas):
    """Devolve a média das notas, ou 0 se a lista estiver vazia."""
    if not notas:
        return 0
    return sum(notas) / len(notas)

def situacao(m, corte=6, recuperacao=4):
    """Aprovado, recuperação ou reprovado, pela média m."""
    if m >= corte:
        return "aprovado"
    if m >= recuperacao:
        return "recuperação"
    return "reprovado"

def linha(nome, notas):
    m = media(notas)
    return f"{nome}: {m:.1f} ({situacao(m)})"
```

